j2:if.script:
function KbArticleRatingClass() {
    var currentId = '$[JS:knowledgeRecord.sys_id]';
    var feedbackRequestState = null;
    var helpfulYesCount = parseInt("${kbViewInfo.helpfulYesCount || 0}");
    var helpfulTotalCount = parseInt("${kbViewInfo.helpfulTotalCount || 0}");
    var isSubmitting = false;

    function ajaxPost(value) {
        if (isSubmitting) {
            return;
        }
        isSubmitting = true;
        if (currentId) {
            var ajax = new GlideAjax('KBAjax');
            ajax.addParam('sysparm_type', 'saveUseful');
            ajax.addParam('sysparm_useful', value);
            ajax.addParam("sysparm_article_id", currentId);
            var query = $j('#sysparm_search');
            ajax.addParam('sysparm_search', (query.length) ? escape(query.val()) : '');
            ajax.addParam("ts_queryId", "${tsQueryId}");
            ajax.getXMLAnswer(function(answer) {
                postUsefulCallback(answer);
                isSubmitting = false;
            });
        } else {
            isSubmitting = false;
        }
    }

    function postUsefulCallback(answer) {
        var data = answer.evalJSON(true);
        if (!data) {
            return kbViewArticle.showErrorMessage('${jvar_failure_message}');
        }
        if (!data.success) {
            return kbViewArticle.showErrorMessage(data.message);
        }
        helpfulTotalCount += 1;
        if (feedbackRequestState === 'yes') {
            helpfulYesCount += 1;
        }
        var newPercent = (helpfulTotalCount > 0) ? Math.round(helpfulYesCount / helpfulTotalCount * 100) : 0;
        var messageTemplate = "${gs.getMessage('{0}% found this useful')}";
        var notification = $j('#kb_feedback_notification');
        if (notification.length > 0) {
            notification.css({
                'position': 'fixed',
                'top': '10px',
                'left': '10px',
                'right': '10px',
                'z-index': '9999',
                'width': 'calc(100% - 20px)',
                'max-width': 'none',
                'margin': '0 auto',
                'box-shadow': '0 2px 8px rgba(0,0,0,0.15)'
            }).fadeIn(300, function() {
                setTimeout(function() {
                    notification.find('.icon-cross.close').focus();
                }, 100);
            });
        }
        var percentageElement = $j('.kb-article-yn-percentage');
        if (percentageElement.length > 0) {
            if (newPercent > 0) {
                messageTemplate = messageTemplate.replace("{0}", newPercent);
                percentageElement.html(
                    '' + "${gs.getMessage('Thank you for your feedback!')}" + ' ' +
                    '' + messageTemplate + ''
                ).css({
                    'display': 'block',
                    'opacity': 0
                }).animate({
                    opacity: 1
                }, 300);
            } else {
                percentageElement.html(
                    '' + "${gs.getMessage('Thank you for your feedback!')}" + ''
                ).css({
                    'display': 'block',
                    'opacity': 0
                }).animate({
                    opacity: 1
                }, 300);
            }
        }
    }

    function feedback(value) {
        if (feedbackRequestState === value) {
            return;
        }
        if (isSubmitting) {
            return;
        }
        feedbackRequestState = value;
        var box = $j('.kb_box_centered');
        box.find('.kb-article-yn-label, .kb-article-yes-btn, .kb-article-no-btn, .kb-article-yn-percentage').fadeOut(200, function() {
            ajaxPost(value);
        });
    }

    function close() {
        var notification = $j('#kb_feedback_notification');
        notification.fadeOut(300, function() {
            notification.css('display', 'none');
        });
    }

    return {
        feedback: feedback,
        close: close
    };
}

// Create instance
if (typeof kbArticleRating === 'undefined') {
    var kbArticleRating = new KbArticleRatingClass();
}
